INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-faruqui-weaponization-order', 'magistrate-judge-faruqui-order-white-house-weaponization-former-fbi-agents', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Federal magistrate judge in Washington accuses the White House of weaponizing law enforcement', 'Magistrate Judge Zia Faruqui issued the written order on Tuesday, Nov. 24, after dismissing a case against two former FBI agents earlier in November, ABC News reported.', 'A federal magistrate judge in Washington, D.C., issued a sharply worded written order on Tuesday, Nov. 24, accusing the White House of the blatant weaponization of federal law enforcement, ABC News reported.

Magistrate Judge Zia Faruqui earlier in November dismissed a criminal case against two former FBI agents who had been accused of lying to Congress about past investigations of Hunter Biden, according to ABC News.

## What the judge wrote

In the order, Faruqui said the administration has described the weaponization of law enforcement as a threat posed by others, and wrote that "now the threat is finally real," ABC News reported. He pointed to the White House as the source, according to the report.

ABC News described the story as developing. Its report did not include a response from the White House or the Justice Department.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b4/Aerial_view_of_National_Building_Museum_and_historic_D.C._Courthouse,_Washington,_D.C_LCCN2010630889.tif/lossy-page1-1280px-Aerial_view_of_National_Building_Museum_and_historic_D.C._Courthouse,_Washington,_D.C_LCCN2010630889.tif.jpg', 'Aerial view of the National Building Museum and the historic D.C. Courthouse at Judiciary Square, Washington (file photo, not the courthouse where Judge Faruqui sits). Carol M. Highsmith Archive, Library of Congress, no known restrictions, via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-25.sql', 8, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261125-faruqui-weaponization-order-src1', 'bd-20261125-faruqui-weaponization-order', '''The threat is finally real'': Judge rips White House ''weaponization''', 'https://abcnews.com/US/threat-finally-real-judge-rips-white-house-weaponization/story?id=138417990', 'ABC News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-25T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-25. Editor to confirm.', 'newsroom-assistant', '2026-11-25T11:00:00.000Z');
