INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-furman-icc-sanctions-ruling', 'judge-furman-permanently-bars-penalties-icc-cooperation-first-amendment-nationwide', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Judge permanently bars the administration from penalizing Americans for helping the International Criminal Court', 'U.S. District Judge Jesse Furman ruled on Monday, Nov. 23, that part of Trump''s ICC sanctions order violates the First Amendment, and applied the protection to all Americans, The Intercept reported.', 'U.S. District Judge Jesse Furman ruled on Monday, Nov. 23, that the Trump administration may not punish Americans for sharing evidence of alleged Israeli war crimes with the International Criminal Court, The Intercept reported.

The ruling also bars penalties for providing information to three sanctioned Palestinian human rights groups, al-Haq, al-Mezan and the Palestinian Center for Human Rights, and to United Nations special rapporteur Francesca Albanese, according to the report.

## The order at issue

Executive Order 14203, issued in February 2025, used financial penalties under the International Emergency Economic Powers Act against the ICC and cited the court''s investigations into Israel, The Intercept reported. Furman found the order''s "services provision" unconstitutional because it undercut First Amendment rights to provide non-financial services to human rights advocates.

## Broader than earlier rulings

An October preliminary injunction protected only the plaintiffs, according to The Intercept. The new permanent ruling is the first to cover all Americans. The lawsuit was filed in July 2026 by Democracy for the Arab World Now (DAWN) and the Taxpayer Alliance Against Genocide.

DAWN executive director Omar Shakir said the ruling takes apart a core part of the sanctions program, according to the report. The White House did not immediately respond to The Intercept''s request for comment. In a filing earlier in November, the administration''s lawyers argued that the order did not restrict free speech.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Thurgood_Marshall_U.S._Courthouse_(Home_of_the_U.S._Court_of_Appeals_for_the_Second_Circuit_and_S.D.N.Y.)_(7237324632).jpg/1280px-Thurgood_Marshall_U.S._Courthouse_(Home_of_the_U.S._Court_of_Appeals_for_the_Second_Circuit_and_S.D.N.Y.)_(7237324632).jpg', 'The Thurgood Marshall U.S. Courthouse in Manhattan (file photo). Photo: Flickr via Wikimedia Commons; editor to confirm the rights statement on the file page (photographer and license not yet confirmed)', 'licensed', 'newsroom', 'content/2026-11-25.sql', 7, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261125-furman-icc-sanctions-ruling-src1', 'bd-20261125-furman-icc-sanctions-ruling', 'Why a Case Against ICC Sanctions Is a Major Victory for Palestine Human Rights Work', 'https://theintercept.com/2026/11/24/icc-sanctions-palestine-israel-human-rights/', 'The Intercept', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-25T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-25. Editor to confirm.', 'newsroom-assistant', '2026-11-25T11:00:00.000Z');
