INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-hubbard-wins-nc5-recount', 'chuck-hubbard-wins-recount-nc-5th-district-unseats-virginia-foxx', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Democrat Chuck Hubbard wins the North Carolina recount and unseats Rep. Virginia Foxx', 'Foxx conceded on Sunday, Nov. 22, after the recount in the 5th District. ABC News said the result gives Democrats their largest House majority since 1992.', 'Democrat Chuck Hubbard has won the recount in North Carolina''s 5th Congressional District, unseating longtime Republican Rep. Virginia Foxx, ABC News reported on Sunday, Nov. 22. The Associated Press projected Hubbard as the winner that day.

With 99% of the estimated vote counted, Hubbard led Foxx 48.7% to 48.6%, a margin of fewer than 300 votes, according to ABC News. Foxx had requested the recount after final state tallies showed her trailing.

## A concession call

Hubbard said on social media that Foxx called him on Sunday to concede, ABC News reported. He thanked her for decades of service. In a statement, Foxx acknowledged his victory and wished him well in representing the district in the 120th Congress.

Hubbard is a former local journalist who lost to Foxx in 2024. Foxx was first elected to the House in 2004 after serving in the North Carolina state Senate, and she chairs the House Rules Committee, according to ABC News.

## The size of the new majority

ABC News said the result gives Democrats their biggest House majority since 1992. As of Sunday, its estimate put Democrats at no fewer than 258 seats and Republicans at no fewer than 173, with four races not yet projected. In North Carolina''s Senate race, former Gov. Roy Cooper, a Democrat, flipped the seat held by retiring Republican Sen. Thom Tillis.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/ba/Blue_Ridge_Parkway-27527.jpg/1280px-Blue_Ridge_Parkway-27527.jpg', 'The Blue Ridge Parkway in North Carolina (file photo). Via Wikimedia Commons; editor to confirm the rights statement on the file page (photographer and license not yet confirmed)', 'licensed', 'newsroom', 'content/2026-11-25.sql', 7, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261125-hubbard-wins-nc5-recount-src1', 'bd-20261125-hubbard-wins-nc5-recount', 'Democrat Chuck Hubbard wins recount in North Carolina US House race, unseats Republican Rep. Virginia Foxx', 'https://abcnews.com/Politics/democrat-chuck-hubbard-wins-recount-north-carolina-us/story?id=138362634', 'ABC News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-25T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-25. Editor to confirm.', 'newsroom-assistant', '2026-11-25T11:00:00.000Z');
