INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-turkey-pardon-freedom-feathers', 'trump-pardons-thanksgiving-turkeys-freedom-feathers-texas-am-2026', 'newsroom', 'news_story', 'white-house', 'EDITORIAL_REVIEW', 0, 'Trump pardons Thanksgiving turkeys Freedom and Feathers, who will retire at Texas A&M', 'The 79th National Thanksgiving Turkey Presentation took place on the White House South Lawn on Tuesday, Nov. 24. The birds were raised on a West Virginia farm.', 'President Trump pardoned the 2026 National Thanksgiving turkeys, Freedom and Feathers, at a ceremony on the White House South Lawn on Tuesday, Nov. 24, according to The Epoch Times and FOX 7 Austin. The White House counts it as the 79th National Thanksgiving Turkey Presentation.

The birds were raised by Scott and Becky Rightsell on their farm in West Virginia, CBS News reported. Their names were chosen through an online White House poll, FOX 7 Austin reported. Before the ceremony the turkeys stayed at the Willard hotel in Washington.

## What the president said

Trump said the full and unconditional pardon means the birds will live forever, according to both reports. He joked that the names were "a little out there," The Epoch Times reported, and said the 2027 ceremony will be held in the White House ballroom now under construction. He also used the event to talk up the economy.

## A new home in Texas

Freedom and Feathers will live at Texas A&M University in College Station, where the school built a climate-controlled home and students will care for them, CBS News reported. They are the first National Thanksgiving turkeys to retire in Texas. Trump said they would be guests at Texas A&M''s game against Texas on Friday, Nov. 27.

The pardon became an annual tradition in 1989 under President George H.W. Bush, CBS News noted.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/President_Trump_Pardons_the_National_Thanksgiving_Turkey_(50642878766).jpg/1280px-President_Trump_Pardons_the_National_Thanksgiving_Turkey_(50642878766).jpg', 'President Trump at the 2020 National Thanksgiving Turkey pardon (file photo, not from the 2026 ceremony). Official White House photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-25.sql', 5, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261125-turkey-pardon-freedom-feathers-src1', 'bd-20261125-turkey-pardon-freedom-feathers', 'Pardoned Thanksgiving turkeys Freedom and Feathers to retire in Texas', 'https://www.yahoo.com/news/us/articles/pardoned-thanksgiving-turkeys-freedom-feathers-010619452.html', 'FOX 7 Austin (via Yahoo News)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-25T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-25. Editor to confirm.', 'newsroom-assistant', '2026-11-25T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261125-turkey-pardon-freedom-feathers-src2', 'bd-20261125-turkey-pardon-freedom-feathers', 'Trump Pardons Turkeys ''Freedom'' and ''Feathers'' in Annual White House Tradition', 'https://www.theepochtimes.com/us/trump-pardons-turkeys-freedom-and-feathers-in-annual-white-house-tradition-6128935', 'The Epoch Times', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-25T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-25. Editor to confirm.', 'newsroom-assistant', '2026-11-25T11:00:00.000Z');
