INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-celtics-beat-wizards-tatum-41', 'celtics-beat-wizards-131-116-tatum-41-snap-four-game-skid-nba-cup', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Tatum scores 41 as the Celtics beat the Wizards 131-116 and snap a four-game skid', 'Boston scored 80 points in the first half in Washington on Tuesday, Nov. 24, and improved to 3-0 in NBA Cup group play.', 'Jayson Tatum scored 41 points and the Celtics beat the Washington Wizards 131-116 at Capital One Arena on Tuesday, Nov. 24, ending a four-game losing streak, the Associated Press reported via ESPN.

Tatum scored 28 of his points in the first half and made 13 of 25 shots, including 6 of 15 from 3-point range, according to the Celtics'' team recap. He added eight assists and six rebounds. It was his highest-scoring game since he scored 46 against Cleveland on Feb. 28, 2025.

## A huge first half

Boston made 10 3-pointers in a 46-point second quarter and led 80-49 at halftime, the AP reported. Washington cut a deficit that reached 34 points down to seven late in the fourth quarter before Baylor Scheierman, scoreless until the final minutes, scored eight straight points to close it out, the team recap said.

Paul George scored 28 points with nine assists and became the eighth player in NBA history to make 2,500 career 3-pointers. Neemias Queta added a season-high 21 points on 9-of-11 shooting.

## Around the game

Anthony Davis led Washington with 33 points and 13 rebounds. Brockton native AJ Dybantsa had 20 points, 11 rebounds and seven assists in his first game against Boston. Coach Joe Mazzulla earned his 250th win in his 346th game, the second-fastest pace behind Steve Kerr.

Boston is 12-6 and 3-0 in NBA Cup play, while Washington (7-12) was eliminated from Cup contention, according to the AP. The Celtics host Atlanta on Friday, Nov. 27.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/ff/Army_vs_Navy_Basketball_game,_2004.jpg/1280px-Army_vs_Navy_Basketball_game,_2004.jpg', 'Army and Navy play college basketball, 2004 (file photo, not from this game). U.S. military photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-25.sql', 8, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
