INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-golden-knights-beat-oilers', 'golden-knights-beat-oilers-5-3-eichel-connelly-two-goals-mcdavid', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Eichel and Connelly score twice each as Vegas beats Edmonton 5-3', 'The Golden Knights won at Rogers Place on Tuesday, Nov. 24, handing the Oilers a fourth straight loss despite a goal from Connor McDavid.', 'Jack Eichel and Trevor Connelly each scored twice, and the Vegas Golden Knights beat the Edmonton Oilers 5-3 at Rogers Place on Tuesday, Nov. 24, NHL.com reported.

Connelly also had an assist, and Mitch Marner added two assists. Carter Hart made 21 saves for Vegas (15-6-5), which has won two straight after a four-game slide.

## How it went

Eichel opened the scoring on a power play in the first period, and Connelly made it 2-0. Edmonton tied the game in the second on goals by Colton Dach and Connor McDavid, whose goal came with 19 seconds left in the period, according to NHL.com.

Nic Dowd put Vegas ahead early in the third, and Eichel scored again to make it 4-2. Vasily Podkolzin answered 16 seconds later, but Connelly sealed it with an empty-net goal.

## Milestones and injuries

Marner became the 15th-fastest player in NHL history to reach 600 assists, and Evan Bouchard set an Oilers record as the fastest defenseman to 40 points in a season, NHL.com reported. McDavid extended a season-opening home point streak to 13 games.

Edmonton (17-6-4) got Ryan Nugent-Hopkins back after a five-game absence, but Filip Hallander left in the first period with a lower-body injury.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Cadet_Field_House_Ice_Arena_USAFA_Colorado_Springs.jpg/1280px-Cadet_Field_House_Ice_Arena_USAFA_Colorado_Springs.jpg', 'The ice arena in the Cadet Field House at the U.S. Air Force Academy, Colorado Springs (file photo, not from this game). Via Wikimedia Commons; editor to confirm the rights statement on the file page (photographer and license not yet confirmed)', 'licensed', 'newsroom', 'content/2026-11-25.sql', 6, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
