INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261125-patriots-devito-starter-maye', 'vrabel-devito-patriots-starter-no-timetable-drake-maye-chargers', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Vrabel says Tommy DeVito is the Patriots starter, with no timetable for Drake Maye', 'Speaking on Monday, Nov. 23, as the 5-5 Patriots returned from their bye, the coach said Maye will not be available for the game against the Chargers.', 'Patriots coach Mike Vrabel said on Monday, Nov. 23, that Tommy DeVito is the team''s starting quarterback and that there is no timetable for Drake Maye''s return, NBC Sports and WJAR reported.

Vrabel told WEEI that Maye will not be available for the Chargers game, according to NBC Sports'' Pro Football Talk. Reports have said Maye fractured his fibula. Vrabel said the exact diagnosis does not change the team''s planning, and he left open the possibility that Maye returns during the 2026 season. Maye has not been moved to injured reserve, WJAR reported.

## The quarterback room

The Patriots (5-5) returned from their bye with a bonus practice ahead of their game against the Chargers. Rookie Behren Morton is the backup, and Vrabel said the team is sticking with DeVito despite reports linking it to Daniel Jones, according to WJAR.

## Other injury news

A.J. Brown is not expected to play because of a hamstring injury. Romeo Doubs and Alijah Vera-Tucker are eligible to return from injured reserve for the Chargers game, WJAR reported. Vera-Tucker practiced on Monday.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/Flying_Tigers_helmet_161229-F-NI493-001.jpg/1280px-Flying_Tigers_helmet_161229-F-NI493-001.jpg', 'A football helmet (file photo, not a Patriots helmet). U.S. Air Force photo (public domain) via Wikimedia Commons; editor to confirm the rights statement on the file page', 'public_domain', 'newsroom', 'content/2026-11-25.sql', 6, 0, 'newsroom-assistant', '2026-11-25T11:00:00.000Z', '2026-11-25T11:00:00.000Z');
